import{_ as t,o as a,c as i,a2 as s}from"./chunks/framework.BxGwJL09.js";const g=JSON.parse('{"title":"Documents & Citations","description":"","frontmatter":{},"headers":[],"relativePath":"documents.md","filePath":"documents.md","lastUpdated":null}'),n={name:"documents.md"};function o(r,e,l,h,d,c){return a(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="Documents-and-Citations" tabindex="-1">Documents &amp; Citations <a class="header-anchor" href="#Documents-and-Citations" aria-label="Permalink to &quot;Documents &amp; Citations {#Documents-and-Citations}&quot;">​</a></h1><p>A notebook is also a <strong>publishable document</strong>. Beyond code and prose it can carry academic front matter — a title block, an abstract, a bibliography — and cite sources inline. Every export target (article/report PDF, slide deck, HTML, a published site) reads the same authored metadata and places it correctly.</p><p>You author document metadata as <strong>ordinary cells</strong> carrying a <em>role tag</em> (set with the 🏷 <a href="./cell-tags">tag editor</a> or a token in the cell header), in natural reading order. Nothing is a special syntax — a <code>title</code> cell is just a markdown cell that the export hoists.</p><h2 id="Front-matter" tabindex="-1">Front matter <a class="header-anchor" href="#Front-matter" aria-label="Permalink to &quot;Front matter {#Front-matter}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Role tag</th><th style="text-align:right;">The cell becomes</th><th style="text-align:right;">Placement on export</th></tr></thead><tbody><tr><td style="text-align:right;"><code>title</code></td><td style="text-align:right;">the title block: <code># Title</code>, then <code>##</code>/<code>###</code> subtitle, then the first plain line as byline</td><td style="text-align:right;">hoisted to the top</td></tr><tr><td style="text-align:right;"><code>abstract</code></td><td style="text-align:right;">an academic abstract</td><td style="text-align:right;">hoisted into the title block</td></tr><tr><td style="text-align:right;"><code>bibliography</code></td><td style="text-align:right;">the reference database (see below)</td><td style="text-align:right;">not shown; drives citations + References</td></tr></tbody></table><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#%% md id=fm title</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Spectral Methods for the Heat Equation</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">### A reproducible study</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Ada Lovelace </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">·</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Analytical Engine Lab</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#%% md id=abs abstract</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">We compare Chebyshev and Fourier spectral discretizations on the </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">D heat</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">equation, and show the reactive notebook that produced every figure.</span></span></code></pre></div><p>With no <code>title</code> cell, the document title falls back to the first markdown <code># H1</code>, then the filename. The title block also feeds the PDF/HTML title, the <a href="./publishing">published-site</a> card, and the OG social-card metadata.</p><h2 id="bibliography" tabindex="-1">Bibliography <a class="header-anchor" href="#bibliography" aria-label="Permalink to &quot;Bibliography&quot;">​</a></h2><p>Tag a markdown cell <code>bibliography</code>. Its body is <strong>either</strong> embedded BibTeX <strong>or</strong> one or more sources, one per line: a <strong><code>.bib</code> file path</strong> (resolved relative to the notebook and copied into exports) or the <strong>address of a knowledge base</strong> (see below). One cell cannot hold both: a cell containing any <code>@entry{…}</code> is read as embedded BibTeX and its other lines are ignored. To use both, write two bibliography cells.</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#%% md id=bib bibliography</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">@book</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{knuth1984,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  author </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {Donald E. Knuth},</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  title  </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {The TeXbook},</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  year   </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1984</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">},</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  publisher </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {Addison</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Wesley}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#%% md id=bibfile bibliography</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">references</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">bib</span></span></code></pre></div><p>In the live notebook, the bibliography renders an adaptive <strong>references card</strong> listing your entries, with the keys you&#39;ve actually cited highlighted.</p><p><img class="slate-shot" src="https://github.com/kahliburke/KaimonSlate.jl/releases/download/docs-assets/references-card.png" alt=""></p><h3 id="A-knowledge-base&#39;s-bibliography" tabindex="-1">A knowledge base&#39;s bibliography <a class="header-anchor" href="#A-knowledge-base&#39;s-bibliography" aria-label="Permalink to &quot;A knowledge base&amp;#39;s bibliography {#A-knowledge-base&#39;s-bibliography}&quot;">​</a></h3><p>A line holding a site&#39;s address takes the bibliography of a <a href="https://github.com/kahliburke/Zemi.jl" target="_blank" rel="noreferrer">Zemi</a> knowledge base: every paper, upload and record you may read there, keyed as Zemi keys them (<code>[@arXiv:2401.01234]</code>, <code>[@doc-…]</code>, <code>[@rec-…]</code>).</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#%% md id=kb bibliography</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">https</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">://</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">kb</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">example</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">org</span></span></code></pre></div><p>The hub fetches it from the site&#39;s <code>api/bib</code> with your API token, keeps a copy, and checks for a newer one when the notebook opens and every few minutes after; the notebook works from the copy, offline too. A line ending in <code>.bib</code> is fetched as given, so any BibTeX file on the web works the same way.</p><p>A Zemi site needs sign-in. Create a token on the site under <strong>Account → API tokens</strong>, with the <strong>read</strong> permission (see <a href="https://kahliburke.github.io/Zemi.jl/" target="_blank" rel="noreferrer">Zemi&#39;s documentation</a>); the references card then shows <strong>Add token</strong> beside the site, which saves it on the hub (<code>secrets.json</code> in the config home) for that host. The token is never written into the notebook. A Zemi run for one person on this machine takes its local key in the same place.</p><p>A library can hold thousands of entries. <code>[@</code> asks the hub for the keys matching what you type, and the card lists only the cited entries once there are more than a few. A PDF, HTML or Markdown export, and a self-contained <code>.jl</code>, carry only the entries the notebook cites.</p><h2 id="Citing-in-prose" tabindex="-1">Citing in prose <a class="header-anchor" href="#Citing-in-prose" aria-label="Permalink to &quot;Citing in prose {#Citing-in-prose}&quot;">​</a></h2><p>Cite a bibliography key from any <strong>markdown</strong> cell. Typing <code>[@</code> autocompletes keys.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Form</th><th style="text-align:right;">Renders (numeric style)</th><th style="text-align:right;">Use</th></tr></thead><tbody><tr><td style="text-align:right;"><code>[@knuth1984]</code></td><td style="text-align:right;"><code>[1]</code></td><td style="text-align:right;">a normal citation</td></tr><tr><td style="text-align:right;"><code>[@knuth1984, pp. 33-35]</code></td><td style="text-align:right;"><code>[1, pp. 33–35]</code></td><td style="text-align:right;">with a page/locator</td></tr><tr><td style="text-align:right;"><code>[@a; @b]</code></td><td style="text-align:right;"><code>[1, 2]</code></td><td style="text-align:right;">several at once</td></tr><tr><td style="text-align:right;"><code>@knuth1984</code></td><td style="text-align:right;"><code>Knuth (1984)</code></td><td style="text-align:right;">a prose (author–year) mention</td></tr></tbody></table><p>The bare <code>@key</code> prose form only converts keys that are actually defined, so an email address or a stray <code>@handle</code> stays literal. On export, citations render <strong>linked</strong> to the References section and a References list is generated in your chosen style; the live notebook mirrors this with the references card.</p><h2 id="Citation-style" tabindex="-1">Citation style <a class="header-anchor" href="#Citation-style" aria-label="Permalink to &quot;Citation style {#Citation-style}&quot;">​</a></h2><p>Pick the citation style per notebook in <strong>Settings → Export → Citation style</strong> (persisted as <code>bibstyle</code> in <a href="/KaimonSlate.jl/dev/settings#This-notebook">Settings, under This notebook</a>):</p><p><code>ieee</code> · <code>american-physics-society</code> · <code>american-institute-of-physics</code> · <code>nature</code> · <code>vancouver</code> · <code>apa</code> · <code>chicago-author-date</code> · <code>harvard-cite-them-right</code> · <code>mla</code> · <code>author-year-brackets</code></p><p>Numeric styles (IEEE, APS, AIP, Nature, Vancouver) render <code>[1]</code> and order the References by first citation. Author–date styles (APA, Chicago, Harvard, MLA) render <code>(Knuth, 1984)</code> and order alphabetically. <code>author-year-brackets</code> is Slate&#39;s own: it cites as <code>[Knuth 1984]</code>, adds <code>a</code>, <code>b</code>, … when two works share an author and year, and keys each References entry by the same label.</p><h2 id="figures" tabindex="-1">Figures <a class="header-anchor" href="#figures" aria-label="Permalink to &quot;Figures&quot;">​</a></h2><p>Tag a markdown cell <strong><code>caption</code></strong> and it captions the output of the cell above it, becoming a <strong>numbered figure</strong> on export (<code>Figure N.</code>). Give it a <code>label=</code> to cross-reference it, and <code>for=</code> to caption a cell other than the one directly above:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#%% md id=cap1 caption label=scaling</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Throughput against core count.</span></span></code></pre></div><p>Refer to it from any markdown cell with <code>[@fig:scaling]</code>, the same cross-reference machinery as citations. That renders as a link in the live notebook and as plain <code>Figure N</code> in the PDF.</p><p>Figures embed as vectors where possible (CairoMakie → PDF, ECharts → SVG) so they stay crisp in print. See <a href="./export">Export</a> and <a href="./visualization">Charts &amp; Tables</a>.</p><div class="tip custom-block"><p class="custom-block-title">From notebook to paper</p><p>Add a <code>title</code> cell, an <code>abstract</code> cell, and a <code>bibliography</code> cell; cite with <code>[@key]</code>; then <strong>Export → PDF (Report, two-column)</strong>. The same notebook is your working analysis <em>and</em> the manuscript that reproduces it.</p></div>`,32)])])}const k=t(n,[["render",o]]);export{g as __pageData,k as default};
